27	/// Result of legal_actions: a list of actions plus an optional combat prompt.
28	/// When a combat prompt is present, the player should construct a
29	/// DeclareAttackers/DeclareBlockers action from it (not pick from the actions list).
30	pub struct LegalActions {
31	    pub actions: Vec<Action>,
32	    pub combat_prompt: Option<crate::actions::CombatPrompt>,
33	    /// Castable spells with valid target options, for interactive target selection.
34	    /// Each entry is one castable spell (collapsed view). The `actions` list still
35	    /// contains the fully-expanded CastSpell entries for LLM/random players.
36	    pub castable_spells: Vec<crate::actions::CastableSpell>,
37	}
38	
39	/// Check if Rooftop Storm is on the battlefield and provides a {0} alternative cost
40	/// for a Zombie creature spell cast by the given player.
